{
  "tools": [
    {
      "name": "ui_probe_batch",
      "title": "Probe Batch",
      "toolset": "ui",
      "description": "Probe a whole list of css cases at once - one cell each, laid out in a grid, measured together and captured as a single contact sheet. This is the parity sweep: state the cases, get every measurement back in one call, then diff them against the same cases in a browser.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cases": {
            "type": "string",
            "description": "One css case per line. Lines starting with # are ignored, so a case file pastes straight in."
          },
          "text": {
            "type": "string",
            "description": "Text to draw, which makes every sample a label instead of a block."
          },
          "background": {
            "type": "string",
            "description": "Colour behind the samples.",
            "default": "#101010"
          },
          "columns": {
            "type": "integer",
            "description": "Cells per row. 0 fits as many as the screen holds.",
            "minimum": 0,
            "maximum": 24,
            "default": 0
          },
          "points": {
            "type": "string",
            "description": "Pixels to read from every sample, as 'x,y x,y'. Empty reads their centres."
          },
          "screenshot": {
            "type": "boolean",
            "description": "Return the contact sheet as well as the numbers.",
            "default": true
          }
        },
        "required": [
          "cases"
        ]
      }
    }
  ],
  "total": 128
}
